package com.nigson.acceptance.pricing;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
public final class PricingHttpAcceptance {
 private PricingHttpAcceptance(){}
 public static void configure(Map<String,Object> properties){if(System.getenv("NIGSON_TEST_PRICING")==null)return;properties.put("NIGSON_CARRIER_ACCOUNT_FINGERPRINT","1".repeat(64));properties.put("NIGSON_PRICING_CHECKOUT_ENABLED","true");properties.put("NIGSON_PRICING_PROVIDER_MODE","MOCK");properties.put("NIGSON_PRICING_PAYMENT_APPROVAL","SYNTHETIC_PAYMENT_NOT_QUALIFIED");properties.put("NIGSON_PRICING_CARRIER_APPROVAL","SYNTHETIC_CARRIER_NOT_QUALIFIED");properties.put("NIGSON_PRICING_PROVIDER_APPROVAL_UNTIL",Instant.now().plusSeconds(3600).toString());}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{if(System.getenv("NIGSON_TEST_PRICING")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var csrf=new ArrayList<String>();try(var f=new PricingFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){for(UUID party:List.of(f.sales.party(),f.finance.party())){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();csrf.add(token);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}String books=base+"/api/v1/staff/price-books",price=base+"/api/v1/catalogue/skus/"+f.sku+"/price?market=NG&quantity=2";var body=EventCodec.JSON.valueToTree(f.input("12.34"));((tools.jackson.databind.node.ObjectNode)body).remove("effectiveUntil");((tools.jackson.databind.node.ObjectNode)body).put("effectiveUntil",Instant.now().plusSeconds(3600).toString());String request=EventCodec.JSON.writeValueAsString(body);assertThat(send(http,HttpRequest.newBuilder(URI.create(books)).GET()).statusCode()).isEqualTo(401);assertThat(send(http,mutation(books,cookies.get(1),csrf.get(1),"create",request)).statusCode()).isEqualTo(403);assertThat(send(http,mutation(books,cookies.getFirst(),"wrong","create",request)).statusCode()).isEqualTo(401);var created=send(http,mutation(books,cookies.getFirst(),csrf.getFirst(),"create",request));assertThat(created.statusCode()).as("create response: %s",created.body()).isEqualTo(201);var draft=EventCodec.JSON.readTree(created.body());UUID id=UUID.fromString(draft.get("id").asString());assertThat(created.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(send(http,mutation(books,cookies.getFirst(),csrf.getFirst(),"create",request)).body()).isEqualTo(created.body());String activation=books+"/"+id+"/activation",reason="{\"reason\":\"Synthetic offline activation\"}";assertThat(send(http,mutation(activation,cookies.getFirst(),csrf.getFirst(),"activate",reason).header("If-Match","\"0\"")).statusCode()).isEqualTo(403);var active=send(http,mutation(activation,cookies.get(1),csrf.get(1),"activate",reason).header("If-Match","\"0\""));assertThat(active.statusCode()).as("activation response: %s",active.body()).isEqualTo(201);assertThat(active.headers().firstValue("ETag")).hasValue("\"1\"");f.jdbc.update("UPDATE commerce.market SET retail_price_book_id=? WHERE id=?",id,f.market);var next=body.deepCopy();((tools.jackson.databind.node.ObjectNode)next).remove("code");Instant boundary=Instant.parse(draft.get("effectiveUntil").asString());((tools.jackson.databind.node.ObjectNode)next).put("effectiveFrom",boundary.toString());((tools.jackson.databind.node.ObjectNode)next).put("effectiveUntil",boundary.plusSeconds(3600).toString());String revisionUri=books+"/"+id+"/revisions",revisionBody=EventCodec.JSON.writeValueAsString(next);assertThat(send(http,mutation(revisionUri,cookies.getFirst(),csrf.getFirst(),"stale-revision",revisionBody).header("If-Match","\"0\"")).statusCode()).isEqualTo(412);var revised=send(http,mutation(revisionUri,cookies.getFirst(),csrf.getFirst(),"revision",revisionBody).header("If-Match","\"1\""));assertThat(revised.statusCode()).as("revision response: %s",revised.body()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(revised.body()).get("revision").asLong()).isEqualTo(2);assertThat(EventCodec.JSON.readTree(revised.body()).get("active").asBoolean()).isFalse();var publicPrice=send(http,HttpRequest.newBuilder(URI.create(price)).GET());assertThat(publicPrice.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(publicPrice.body()).get("unitAmount").asString()).isEqualTo("12.34");assertThat(publicPrice.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(send(http,HttpRequest.newBuilder(URI.create(price+"&quantity=3")).GET()).statusCode()).isEqualTo(400);assertThat(send(http,HttpRequest.newBuilder(URI.create(price+"&organizationId="+UUID.randomUUID())).GET()).statusCode()).isEqualTo(401);assertThat(send(http,HttpRequest.newBuilder(URI.create(price)).header("Authorization","Bearer browser-token").GET()).statusCode()).isEqualTo(401);var page=send(http,HttpRequest.newBuilder(URI.create(books+"?segment=RETAIL&size=100")).header("Cookie",cookies.getFirst()).GET());assertThat(page.statusCode()).isEqualTo(200);assertThat(send(http,HttpRequest.newBuilder(URI.create(books+"?sort=sql,asc")).header("Cookie",cookies.getFirst()).GET()).statusCode()).isEqualTo(400);var quoteRequest=EventCodec.JSON.valueToTree(f.quoteInput());((tools.jackson.databind.node.ObjectNode)quoteRequest).remove("couponCode");String quote=base+"/api/v1/checkout/quotes",quoteBody=EventCodec.JSON.writeValueAsString(quoteRequest);var snapshot=send(http,mutation(quote,cookies.getFirst(),csrf.getFirst(),"quote",quoteBody));assertThat(snapshot.statusCode()).as("quote response: %s",snapshot.body()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(snapshot.body()).get("totals").get("grandTotal").asString()).isEqualTo("28.13");assertThat(send(http,mutation(quote,cookies.getFirst(),csrf.getFirst(),"quote",quoteBody)).body()).isEqualTo(snapshot.body());assertThat(send(http,mutation(quote,cookies.get(1),csrf.get(1),"foreign",quoteBody)).statusCode()).isEqualTo(404);assertThat(send(http,mutation(quote,cookies.getFirst(),csrf.getFirst(),"unknown",quoteBody.replace("}",",\"amount\":\"0\"}"))).statusCode()).isEqualTo(400);var metrics=app.getBean(io.micrometer.core.instrument.MeterRegistry.class);assertThat(metrics.get("nigson.pricing.commands").tag("operation","CREATE").counter().count()).isEqualTo(1);assertThat(metrics.get("nigson.pricing.commands").tag("operation","ACTIVATE").counter().count()).isEqualTo(1);assertThat(metrics.get("nigson.pricing.commands").tag("operation","QUOTE").counter().count()).isEqualTo(1);f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='SALES'",f.sales.party());assertThat(send(http,mutation(books,cookies.getFirst(),csrf.getFirst(),"create",request)).statusCode()).isEqualTo(403);}finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}}
 private static HttpRequest.Builder mutation(String uri,String cookie,String csrf,String key,String body){return HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
